/**
 * Nodo n8n: "2-3. Traer contexto + armar prompt Edit Director"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 *
 * Input: un item de raw_videos (status='assets_ready'), proveniente del
 * loop "Procesar de a uno".
 *
 * Hace las 4 lecturas de Supabase relacionadas al video (transcript,
 * analysis, assets, brand_kit) + trae el system prompt ya armado desde
 * edit-spec-api, y arma el user prompt específico de este video.
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, EDIT_SPEC_API_URL
 */
const rawVideo = $json;

const SUPABASE_URL = $env.SUPABASE_URL;
const EDIT_SPEC_API_URL = $env.EDIT_SPEC_API_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
};

async function getOne(query) {
  const rows = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/${query}`,
    headers: SUPABASE_HEADERS,
    json: true,
  });
  return Array.isArray(rows) ? rows[0] : rows;
}

const [transcript, analysis, assets, brandKit, promptRes] = await Promise.all([
  getOne(`transcripts?raw_video_id=eq.${rawVideo.id}&select=text_full,words,language`),
  getOne(`analyses?raw_video_id=eq.${rawVideo.id}&select=tema,categoria,hook_principal,hook_score,score_calidad,descripcion_objetivo`),
  getOne(`assets?raw_video_id=eq.${rawVideo.id}&select=titulos,captions_ig,captions_tiktok,hashtags,hooks_alternativos,recomendacion_edicion`),
  getOne(`brand_kit?client_id=eq.${rawVideo.client_id}&select=logo_url,primary_color,accent_color,handle_instagram,handle_tiktok,end_card_cta`),
  this.helpers.httpRequest({
    method: 'GET',
    url: `${EDIT_SPEC_API_URL}/prompts/edit-director-system`,
    json: true,
  }),
]);

if (!transcript || !transcript.words || transcript.words.length === 0) {
  throw new Error(`raw_video ${rawVideo.id} no tiene transcripción con timestamps por palabra todavía.`);
}
if (!analysis || !assets || !brandKit) {
  throw new Error(`raw_video ${rawVideo.id} está marcado assets_ready pero falta analysis/assets/brand_kit en Supabase.`);
}

// Heurística de duración objetivo: ~85% del bruto, acotada a [15,60]s.
// Punto de partida razonable -- el Edit Director puede ajustar los cortes
// para acercarse, no tiene que calzar exacto.
const targetSec = Math.min(60, Math.max(15, Math.round(rawVideo.duration_sec * 0.85)));

const today = new Date().toISOString().slice(0, 10);
// Sufijo numérico de 3 dígitos derivado del uuid, para no depender de un
// contador aparte -- suficiente para no colisionar dentro del mismo día.
const idDigits = String(parseInt(rawVideo.id.replace(/-/g, '').slice(0, 6), 16) % 1000).padStart(3, '0');
const videoId = `VID-${today}-${idDigits}`;

// MVP de este flujo: siempre instagram_reels. Multi-plataforma se resuelve
// generando un edit_spec por plataforma cuando se conecte la Capa 6.
const platform = 'instagram_reels';

const sourceVideoUrl = `${SUPABASE_URL}/storage/v1/object/public/raw/${rawVideo.client_id}/${rawVideo.storage_path}`;

const wordsFormatted = transcript.words
  .map((w) => `[${w.start.toFixed(2)}-${w.end.toFixed(2)}] ${w.word}`)
  .join(' ');

const userPrompt = [
  '## Datos fijos (copiar tal cual en el JSON de salida)',
  `video_id: ${videoId}`,
  `client_id: ${rawVideo.client_id}`,
  `raw_video_id: ${rawVideo.id}`,
  `platform: ${platform}`,
  `source_video.url: ${sourceVideoUrl}`,
  `source_video.duration_sec: ${rawVideo.duration_sec}`,
  `duration.target_sec: ${targetSec}`,
  `branding.logo_url: ${brandKit.logo_url}`,
  `branding.primary_color: ${brandKit.primary_color}`,
  `branding.accent_color: ${brandKit.accent_color}`,
  `branding.handle: ${brandKit.handle_instagram}`,
  'meta.created_by: llm_edit_director',
  `meta.created_at: ${new Date().toISOString()}`,
  'meta.version: 1',
  '',
  '## Análisis previo',
  `tema: ${analysis.tema}`,
  `categoria: ${analysis.categoria}`,
  `hook_principal detectado: ${analysis.hook_principal}`,
  `hook_score previo: ${analysis.hook_score}/10`,
  `score_calidad previo: ${analysis.score_calidad}/10`,
  '',
  '## Hooks alternativos ya generados (podés usarlos o reescribir el propio)',
  JSON.stringify(assets.hooks_alternativos || []),
  '',
  '## Transcripción completa con timestamps por palabra (línea de tiempo del video FUENTE)',
  wordsFormatted,
].join('\n');

return [{
  json: {
    raw_video: rawVideo,
    video_id: videoId,
    platform,
    target_sec: targetSec,
    source_video_url: sourceVideoUrl,
    attempt: 1,
    system_prompt: promptRes.text,
    user_prompt: userPrompt,
  },
}];

/**
 * Nodo n8n: "4. Llamar LLM (Edit Director)"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 *
 * Se reutiliza para el primer intento Y para cada reintento de reparación
 * (el nodo "Repair loop" reescribe system_prompt/user_prompt y vuelve a
 * conectar acá). No sabe ni le importa si es intento 1 o 3 -- solo llama
 * al LLM con lo que tenga en el item.
 *
 * Env vars usadas: ANTHROPIC_API_KEY, ANTHROPIC_VERSION, EDIT_DIRECTOR_MODEL
 */
const ANTHROPIC_API_KEY = $env.ANTHROPIC_API_KEY;
const ANTHROPIC_VERSION = $env.ANTHROPIC_VERSION || '2023-06-01';
const MODEL = $env.EDIT_DIRECTOR_MODEL;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: {
    'x-api-key': ANTHROPIC_API_KEY,
    'anthropic-version': ANTHROPIC_VERSION,
    'content-type': 'application/json',
  },
  body: {
    model: MODEL,
    max_tokens: 4096,
    // Más determinístico en los reintentos de reparación que en el
    // primer intento (menos margen creativo cuando ya sabemos qué falló).
    temperature: $json.attempt > 1 ? 0.2 : 0.4,
    system: $json.system_prompt,
    messages: [{ role: 'user', content: $json.user_prompt }],
  },
  json: true,
});

const rawText = (response.content || []).map((block) => block.text || '').join('');
const cleaned = rawText
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '');

let editSpecCandidate = null;
let parseOk = true;
let parseErrorMessage = null;

try {
  editSpecCandidate = JSON.parse(cleaned);
} catch (err) {
  parseOk = false;
  parseErrorMessage = err.message;
}

return [{
  json: {
    ...$json,
    llm_raw_text: rawText,
    parse_ok: parseOk,
    edit_spec_candidate: editSpecCandidate,
    parse_error_message: parseErrorMessage,
  },
}];

/**
 * Nodo n8n: "5-6. Validar edit_spec"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 *
 * Si el LLM devolvió algo que ni siquiera parsea como JSON, no llama al
 * servicio de validación -- arma directamente el mismo shape de error que
 * devolvería, para que el resto del flujo no tenga que distinguir "no
 * parseó" de "parseó pero es inválido".
 *
 * Env vars usadas: EDIT_SPEC_API_URL
 */
const EDIT_SPEC_API_URL = $env.EDIT_SPEC_API_URL;

let validation;

if (!$json.parse_ok) {
  validation = {
    valid: false,
    errors: [{
      path: '(root)',
      message: `La respuesta del LLM no es JSON válido: ${$json.parse_error_message}`,
    }],
  };
} else {
  validation = await this.helpers.httpRequest({
    method: 'POST',
    url: `${EDIT_SPEC_API_URL}/validate`,
    body: { edit_spec: $json.edit_spec_candidate },
    json: true,
  });
}

return [{ json: { ...$json, validation } }];

/**
 * Nodo n8n: "7. Guardar edit_spec en Supabase"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 * Solo se ejecuta en la rama "válido" del IF.
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};

const inserted = await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/rest/v1/edit_specs`,
  headers: SUPABASE_HEADERS,
  body: {
    raw_video_id: $json.raw_video.id,
    template_id: $json.validation.data.template_id,
    spec_json: $json.validation.data,
    schema_version: $json.validation.data.schema_version,
    version: 1,
    status: 'ready',
    validation_status: 'valid',
    repair_attempts: $json.attempt - 1,
  },
  json: true,
});

return [{ json: { ...$json, edit_spec_id: inserted[0].id } }];

/**
 * Nodo n8n: "8. Actualizar estado -> edit_spec_ready"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
};

await this.helpers.httpRequest({
  method: 'PATCH',
  url: `${SUPABASE_URL}/rest/v1/raw_videos?id=eq.${$json.raw_video.id}`,
  headers: SUPABASE_HEADERS,
  body: { status: 'edit_spec_ready' },
  json: true,
});

return [{ json: $json }];

/**
 * Nodo n8n: "Repair loop: construir prompt de reparación"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 *
 * Solo se ejecuta en la rama "inválido + quedan intentos" del segundo IF.
 * Su output vuelve a conectarse al nodo "4. Llamar LLM (Edit Director)",
 * cerrando el ciclo del repair loop.
 *
 * Env vars usadas: EDIT_SPEC_API_URL
 */
const EDIT_SPEC_API_URL = $env.EDIT_SPEC_API_URL;

const repairPrompt = await this.helpers.httpRequest({
  method: 'POST',
  url: `${EDIT_SPEC_API_URL}/repair-prompt`,
  body: {
    edit_spec: $json.edit_spec_candidate,
    errors: $json.validation.errors,
  },
  json: true,
});

return [{
  json: {
    ...$json,
    attempt: $json.attempt + 1,
    system_prompt: repairPrompt.system,
    user_prompt: repairPrompt.user,
  },
}];

/**
 * Nodo n8n: "Marcar failed_edit_spec_generation (agotados los intentos)"
 * Tipo: Code (JavaScript, "Run Once for Each Item")
 *
 * Se ejecuta cuando se agotaron los 3 intentos y el edit_spec sigue
 * inválido. Guarda el último intento fallido para auditoría (nunca se
 * borran los intentos fallidos, ver sistema-fabrica-reels-nexoia.md) y
 * deja el video en un estado que un humano tiene que revisar a mano.
 *
 * Env vars usadas: SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_HEADERS = {
  apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};

await this.helpers.httpRequest({
  method: 'PATCH',
  url: `${SUPABASE_URL}/rest/v1/raw_videos?id=eq.${$json.raw_video.id}`,
  headers: SUPABASE_HEADERS,
  body: { status: 'failed_edit_spec_generation' },
  json: true,
});

await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPABASE_URL}/rest/v1/edit_specs`,
  headers: SUPABASE_HEADERS,
  body: {
    raw_video_id: $json.raw_video.id,
    template_id: 'personal_brand_clean',
    spec_json: $json.edit_spec_candidate,
    version: 1,
    status: 'draft',
    validation_status: 'invalid',
    validation_errors: $json.validation.errors,
    repair_attempts: $json.attempt,
  },
  json: true,
});

return [{ json: $json }];
